export function TreeShaking({
  libraryName = "{{libraryName}}",
  stage = "{{stage}}",
  accent = "{{accent}}",
  showSizes = {{showSizes}},
}) {
  const before = stage === "before";
  const unusedBadge = { fontSize: 9, fontWeight: 700, padding: "2px 7px", borderRadius: 999, background: "#24143018", color: "#24143099", marginLeft: "auto", textDecoration: before ? "none" : "line-through" };
  return (
    <div role="img" aria-label={`${libraryName} bundle, ${stage} tree-shaking`} style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>import {libraryName}</p>
      <ul style={{ listStyle: "none", margin: "0 0 10px", padding: 0, display: "flex", flexDirection: "column", gap: 6 }}>
        <li style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", borderRadius: 6, fontSize: 11, fontWeight: 600, background: accent }}>
          formatDate() {before && <span style={{ fontSize: 9, fontWeight: 700, padding: "2px 7px", borderRadius: 999, background: "#241430", color: "#FAF7F2", marginLeft: "auto" }}>used</span>}
        </li>
        <li style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", borderRadius: 6, fontSize: 11, fontWeight: 600, background: "#24143010", opacity: before ? 1 : .3 }}>parseTimezone()<span style={unusedBadge}>{before ? "unused" : "removed"}</span></li>
        <li style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", borderRadius: 6, fontSize: 11, fontWeight: 600, background: "#24143010", opacity: before ? 1 : .3 }}>formatCalendar()<span style={unusedBadge}>{before ? "unused" : "removed"}</span></li>
      </ul>
      {showSizes && <p style={{ margin: 0, fontSize: 10, color: "#24143099" }}>{before ? "Bundle size: 48KB (all exports included)" : "Bundle size: 6KB (unused exports removed)"}</p>}
    </div>
  );
}
